def test_the_cursor_nudge_is_bounded_then_falls_back_to_the_opposite_button():
    mem = {}
    box = menu_screen(cursor=208)
    results = []
    for _ in range(O.BATTLE_MENU_HOLD_ADVANCE * 4):
        result = O.battle_menu_hold_advance(box, mem, [O.pad('a')], 'same')
        if result:
            results.append(result)
    assert results.count([O.pad('up')]) == O.BATTLE_MENU_CURSOR_NUDGES
    assert results[-1] == [O.pad('b')]


