def test_a_four_frame_blink_on_the_command_box_is_still_escaped():
    """g1190: the idle sprite cycles four digests; it is still one screen."""
    mem = {}
    box = menu_screen(cursor=208)
    frames = ['blink-a', 'blink-b', 'blink-c', 'blink-d'] * O.BATTLE_MENU_HOLD_ADVANCE
    results = [O.battle_menu_hold_advance(box, mem, [O.pad('a')], d) for d in frames]
    # One full cycle has to be seen before the frame counts as unchanged, and
